// UTF-8 encoding helpers working purely on hex strings.

// Encode a JS string to UTF-8, returned as a lowercase hex string
// (equivalent to Python's str.encode('utf-8')).
export function utf8ToHex(str) {
  let hex = '';
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      hex += cp.toString(16).padStart(2, '0');
    } else if (cp < 0x800) {
      hex += (0xc0 | (cp >> 6)).toString(16);
      hex += (0x80 | (cp & 0x3f)).toString(16).padStart(2, '0');
    } else if (cp < 0x10000) {
      hex += (0xe0 | (cp >> 12)).toString(16);
      hex += (0x80 | ((cp >> 6) & 0x3f)).toString(16).padStart(2, '0');
      hex += (0x80 | (cp & 0x3f)).toString(16).padStart(2, '0');
    } else {
      hex += (0xf0 | (cp >> 18)).toString(16);
      hex += (0x80 | ((cp >> 12) & 0x3f)).toString(16).padStart(2, '0');
      hex += (0x80 | ((cp >> 6) & 0x3f)).toString(16).padStart(2, '0');
      hex += (0x80 | (cp & 0x3f)).toString(16).padStart(2, '0');
    }
  }
  return hex;
}

// Convert a pure-ASCII string (e.g. a Base58 result) to a hex string.
export function asciiToHex(str) {
  let hex = '';
  for (let i = 0; i < str.length; i++) {
    hex += str.charCodeAt(i).toString(16).padStart(2, '0');
  }
  return hex;
}

// Manual Base58 implementation (Bitcoin alphabet), reimplemented from the
// observable behavior of the Python `base58` package. Byte strings are
// represented as lowercase hex strings throughout; arithmetic uses BigInt.

export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const BASE = 58n;
const INDEX = new Map([...ALPHABET].map((ch, i) => [ch, BigInt(i)]));

const ASCII_WHITESPACE = new Set([' ', '\t', '\n', '\r', '\x0b', '\x0c']);

// Equivalent of Python bytes.rstrip(): strip trailing ASCII whitespace.
function rstripAscii(str) {
  let end = str.length;
  while (end > 0 && ASCII_WHITESPACE.has(str[end - 1])) end--;
  return str.slice(0, end);
}

function hexToBigInt(hex) {
  return hex === '' ? 0n : BigInt('0x' + hex);
}

function bigIntToHex(value) {
  if (value === 0n) return '';
  let hex = value.toString(16);
  return hex.length % 2 === 1 ? '0' + hex : hex;
}

// b58encode: hex-encoded bytes -> Base58 string.
// Each leading zero byte becomes a leading '1'.
export function b58encodeHex(hex) {
  let zeros = 0;
  while (zeros * 2 < hex.length && hex.slice(zeros * 2, zeros * 2 + 2) === '00') {
    zeros++;
  }
  let acc = hexToBigInt(hex.slice(zeros * 2));
  let digits = '';
  while (acc > 0n) {
    const mod = acc % BASE;
    digits = ALPHABET[Number(mod)] + digits;
    acc = acc / BASE;
  }
  return '1'.repeat(zeros) + digits;
}

// b58decode: Base58 string -> hex-encoded bytes.
// Trailing ASCII whitespace is stripped first; each leading '1' becomes a
// zero byte. Invalid characters raise an error like Python's ValueError.
export function b58decodeToHex(str) {
  const v = rstripAscii(str);
  let ones = 0;
  while (ones < v.length && v[ones] === '1') ones++;
  let acc = 0n;
  for (let i = ones; i < v.length; i++) {
    const idx = INDEX.get(v[i]);
    if (idx === undefined) {
      throw new Error(`Invalid character '${v[i]}'`);
    }
    acc = acc * BASE + idx;
  }
  return '00'.repeat(ones) + bigIntToHex(acc);
}

// b58encode_int: non-negative integer -> Base58 string (0 encodes to '1').
export function b58encodeInt(value) {
  let n = BigInt(value);
  if (n < 0n) {
    throw new Error('cannot encode negative integer');
  }
  let digits = '';
  while (n > 0n) {
    const mod = n % BASE;
    digits = ALPHABET[Number(mod)] + digits;
    n = n / BASE;
  }
  return digits === '' ? '1' : digits;
}

// b58decode_int: Base58 string -> BigInt ('' and '1' both decode to 0).
export function b58decodeInt(str) {
  const v = rstripAscii(str);
  let acc = 0n;
  for (let i = 0; i < v.length; i++) {
    const idx = INDEX.get(v[i]);
    if (idx === undefined) {
      throw new Error(`Invalid character '${v[i]}'`);
    }
    acc = acc * BASE + idx;
  }
  return acc;
}

// Base58Check: payload + first 4 bytes of double-SHA-256, then Base58.
// Payloads are lowercase hex strings; hashing goes through node:crypto
// using hex input/output encodings only.

import { createHash } from 'node:crypto';
import { b58encodeHex, b58decodeToHex } from './base58.mjs';

export function sha256Hex(hex) {
  return createHash('sha256').update(hex, 'hex').digest('hex');
}

function checksumHex(payloadHex) {
  return sha256Hex(sha256Hex(payloadHex)).slice(0, 8);
}

// b58encode_check: hex payload -> Base58Check string.
export function b58encodeCheckHex(payloadHex) {
  return b58encodeHex(payloadHex + checksumHex(payloadHex));
}

// b58decode_check: Base58Check string -> hex payload; verifies the checksum.
export function b58decodeCheckHex(encoded) {
  const hex = b58decodeToHex(encoded);
  const payload = hex.slice(0, -8);
  const check = hex.slice(-8);
  if (checksumHex(payload) !== check) {
    throw new Error('Invalid checksum');
  }
  return payload;
}

// Reproduce CPython's repr() of a bytes object, given the bytes as a
// lowercase hex string. Mirrors CPython's bytes_repr: single quotes by
// default, double quotes when the data contains "'" but not '"'; escapes
// \\, \t, \n, \r, the active quote, and \xHH for non-printable bytes.

export function reprBytesFromHex(hex) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < hex.length; i += 2) {
    const b = parseInt(hex.slice(i, i + 2), 16);
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (let i = 0; i < hex.length; i += 2) {
    const b = parseInt(hex.slice(i, i + 2), 16);
    if (b === 0x5c || String.fromCharCode(b) === quote) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

// Minimal argparse-compatible command-line parser for this script's
// argument specification: --a..--d are required strings, --e/--f are
// required ints. Supports "--name value" and "--name=value" forms.

const SPEC = [
  { name: 'a', type: 'str' },
  { name: 'b', type: 'str' },
  { name: 'c', type: 'str' },
  { name: 'd', type: 'str' },
  { name: 'e', type: 'int' },
  { name: 'f', type: 'int' },
];

const PROG = 'test19.mjs';

function usage() {
  return `usage: ${PROG} [-h] --a A --b B --c C --d D --e E --f F`;
}

function fail(message) {
  console.error(usage());
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

// Mirror Python's int(): optional surrounding whitespace, optional sign,
// digits with optional single underscores between digits.
function parseIntValue(raw, name) {
  const s = raw.trim();
  if (!/^[+-]?\d(_?\d)*$/.test(s)) {
    fail(`argument --${name}: invalid int value: '${raw}'`);
  }
  return BigInt(s.replace(/_/g, ''));
}

export function parseArgs(argv) {
  const values = new Map();
  const known = new Map(SPEC.map((s) => [s.name, s]));

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    let name;
    let inlineValue;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq === -1) {
        name = token.slice(2);
        inlineValue = undefined;
      } else {
        name = token.slice(2, eq);
        inlineValue = token.slice(eq + 1);
      }
    } else {
      fail(`unrecognized arguments: ${token}`);
    }

    const spec = known.get(name);
    if (spec === undefined) {
      fail(`unrecognized arguments: ${token}`);
    }

    let raw;
    if (inlineValue !== undefined) {
      raw = inlineValue;
      i += 1;
    } else {
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      raw = argv[i + 1];
      i += 2;
    }

    values.set(name, spec.type === 'int' ? parseIntValue(raw, name) : raw);
  }

  const missing = SPEC.filter((s) => !values.has(s.name)).map((s) => `--${s.name}`);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  const result = {};
  for (const spec of SPEC) {
    result[spec.name] = values.get(spec.name);
  }
  return result;
}

// Node.js (ESM) port of /workspace/dataset/base58/test19.py.
// Byte strings flow through the pipeline as lowercase hex strings and are
// printed with CPython's bytes repr formatting.

import { parseArgs } from './lib/cli.mjs';
import { utf8ToHex, asciiToHex } from './lib/utf8.mjs';
import {
  b58encodeHex,
  b58decodeToHex,
  b58encodeInt,
  b58decodeInt,
} from './lib/base58.mjs';
import { b58encodeCheckHex, b58decodeCheckHex } from './lib/checksum.mjs';
import { reprBytesFromHex } from './lib/pybytes.mjs';

const args = parseArgs(process.argv.slice(2));

// repr() of a Base58 result (pure ASCII) as a Python bytes object.
const reprAscii = (s) => reprBytesFromHex(asciiToHex(s));

// 大规模混合操作
const encodedA = b58encodeHex(utf8ToHex(args.a)); // 编码A
const decodedB = b58decodeToHex(args.b); // 解码B
const encodedCheckC = b58encodeCheckHex(utf8ToHex(args.c)); // 带校验和编码C
const decodedCheckC = b58decodeCheckHex(encodedCheckC); // 带校验和解码C
const encodedD = b58encodeHex(utf8ToHex(args.d)); // 编码D
const decodedD = b58decodeToHex(encodedD); // 解码D
const encodedIntE = b58encodeInt(args.e); // 编码整数E
const encodedIntF = b58encodeInt(args.f); // 编码整数F
const decodedIntE = b58decodeInt(encodedIntE); // 解码整数E
const encodedCheckDecoded = b58encodeCheckHex(decodedB); // 带校验和编码解码后的B

console.log(reprAscii(encodedA));
console.log(reprBytesFromHex(decodedB));
console.log(reprAscii(encodedCheckC));
console.log(reprBytesFromHex(decodedCheckC));
console.log(reprAscii(encodedD));
console.log(reprBytesFromHex(decodedD));
console.log(reprAscii(encodedIntE));
console.log(reprAscii(encodedIntF));
console.log(decodedIntE.toString());
console.log(reprAscii(encodedCheckDecoded));
